glsl:
void mainImage(out vec4 fragColor, in vec2 uv, in float time) {
    vec2 p = uv * 2.0 - 1.0;
    float r = length(p);

    // Rising heat turbulence
    float flameShape = r - (0.65 - (p.y + 0.5) * 0.4) + sin(p.x * 6.0 + time * 6.28) * 0.12;
    if (flameShape > 0.05 || p.y < -0.85) {
        fragColor = vec4(0.0);
        return;
    }

    float intensity = clamp(1.0 - flameShape * 1.5, 0.0, 1.0);
    vec3 col = vec3(min(1.0, intensity * 1.4), clamp((intensity - 0.3) * 1.5, 0.0, 1.0), clamp((intensity - 0.8) * 3.0, 0.0, 1.0));
    fragColor = vec4(col, 1.0);
}
